                .map(p -> PersonView.of(p, summaries.getOrDefault(p.getId(), StatementSummary.NONE), today,
                        clashing.test(p)))
                .toList());
    }

    @ViewerAllowed
    @PostMapping("/retire")
    public Retired retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkRetireForm form) {
        String sheet = sheetId.trim();
        List<Person> saved = service.retire(sheet, user.trim(), form.personIds(), form.from());
        Map<Long, StatementSummary> summaries = statements.summaries(sheet);
        LocalDate today = sheets.today(sheet);
        Predicate<Person> clashing = service.clashing(sheet);
        return new Retired(saved.size(), saved.stream()
                .map(p -> PersonView.of(p, summaries.getOrDefault(p.getId(), StatementSummary.NONE), today,
                        clashing.test(p)))
                .toList());
    }

    @PostMapping("/{personId}/aliases")
    public PersonView addAlias(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody AliasForm form) {
        Person saved = service.addAlias(sheetId.trim(), user.trim(), personId, form.alias().trim());
        return PersonView.of(saved, statements.summary(sheetId.trim(), personId), sheets.today(sheetId.trim()),
                service.clashing(sheetId.trim(), saved));
    }

    /** Merge the person into another; answers with the other as they now stand. */
    @PostMapping("/{personId}/merge")
    public PersonView merge(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MergeForm form) {
        Person saved = merges.merge(sheetId.trim(), user.trim(), personId, form.intoId());
        return PersonView.of(saved, statements.summary(sheetId.trim(), saved.getId()), sheets.today(sheetId.trim()),
                service.clashing(sheetId.trim(), saved));
    }

    /** Transfer the person to another sheet; they leave this one. */
    @PostMapping("/{personId}/transfer")
    public void transfer(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody TransferForm form) {
        transfers.transfer(sheetId.trim(), user.trim(), personId, form.toSheet().trim());
    }

    /** The flag form: a required reason and the last day the flag is in force. */
    public record FlagForm(@Size(max = 200) String reason, LocalDate until) {
    }

    /** The approver form: the user who may approve or reject the person's pending claims (blank: none). */
    public record ApproverForm(@Size(max = 100) String user) {
    }

    /** Undo the transfer that brought the person to this sheet today; they go back to where they
     *  came from. */
    @PostMapping("/{personId}/transfer-undo")
    public void transferUndo(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        transfers.undo(sheetId.trim(), user.trim(), personId);
    }

    /** Swap the person with the one above or below them; answers the people in their new order. */
    @PostMapping("/{personId}/move")
    public List<PersonView> move(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MoveForm form) {
        String sheet = sheetId.trim();
        List<Person> listed = service.move(sheet, user.trim(), personId, "up".equals(form.direction()));
        Map<Long, StatementSummary> summaries = statements.summaries(sheet);
        LocalDate today = sheets.today(sheet);
        Predicate<Person> clashing = service.clashing(sheet);
        return listed.stream()
                .map(p -> PersonView.of(p, summaries.getOrDefault(p.getId(), StatementSummary.NONE), today,
                        clashing.test(p)))
                .toList();
    }

